<?php
require_once __DIR__.'/../includes/validation.php';require_once __DIR__.'/../includes/csrf.php';require_once __DIR__.'/../includes/permissions.php';require_role('admin');
$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$action=(string)($_POST['action']??'');
    try{
        if($action==='category'){$name=post_string('name',100);if($name==='')throw new InvalidArgumentException('Category name is required.');$pdo->prepare('INSERT INTO question_categories(name,sort_order) VALUES(?,?)')->execute([$name,(int)($_POST['sort_order']??0)]);}
        elseif($action==='question'){$prompt=post_string('prompt',500);$type=(string)($_POST['question_type']??'rating');$category=(int)($_POST['category_id']??0);if($prompt===''||!in_array($type,['rating','text'],true)||!$category)throw new InvalidArgumentException('Complete all question fields.');$pdo->prepare('INSERT INTO questions(category_id,prompt,question_type,is_required,sort_order) VALUES(?,?,?,?,?)')->execute([$category,$prompt,$type,isset($_POST['is_required'])?1:0,(int)($_POST['sort_order']??0)]);}
        elseif($action==='toggle'){$pdo->prepare('UPDATE questions SET is_active=1-is_active WHERE id=?')->execute([(int)$_POST['question_id']]);}
        else throw new InvalidArgumentException('Unknown action.');
        audit('configure','questionnaire');flash('Questionnaire updated.');redirect('admin/questionnaire.php');
    }catch(Throwable $exception){$error=$exception instanceof InvalidArgumentException?$exception->getMessage():($exception->getCode()==='23000'?'That category already exists.':'Could not save the questionnaire change.');}
}
$categories=$pdo->query('SELECT * FROM question_categories ORDER BY sort_order,name')->fetchAll();
$questions=$pdo->query('SELECT q.*,c.name category FROM questions q JOIN question_categories c ON c.id=q.category_id ORDER BY c.sort_order,q.sort_order,q.id')->fetchAll();
$pageTitle='Questionnaire';require __DIR__.'/../includes/header.php';
?>
<div class="page-heading"><div><div class="eyebrow">EVALUATION FORM</div><h1>Questionnaire</h1><p>Manage rating categories and the questions students see in the active evaluation form.</p></div></div><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?>
<div class="two-column"><section class="panel"><div class="eyebrow">ADD CONTENT</div><h2>New category</h2><form method="post" class="form-stack compact-form"><?=csrf_field()?><input type="hidden" name="action" value="category"><label>Category name<input name="name" maxlength="100" required></label><label>Display order<input name="sort_order" type="number" value="0"></label><button class="button button-quiet">Add category</button></form><hr><h2>New question</h2><form method="post" class="form-stack"><?=csrf_field()?><input type="hidden" name="action" value="question"><label>Category<select name="category_id" required><?php foreach($categories as $c):?><option value="<?= (int)$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Question text<textarea name="prompt" maxlength="500" required></textarea></label><div class="field-row"><label>Response type<select name="question_type"><option value="rating">1–5 rating</option><option value="text">Written response</option></select></label><label>Order<input name="sort_order" type="number" value="0"></label></div><label class="checkbox-label"><input type="checkbox" name="is_required" checked> Required question</label><button class="button button-primary">Add question</button></form></section><section class="panel"><div class="eyebrow">FORM ITEMS</div><h2>Questions</h2><div class="question-admin-list"><?php foreach($questions as $q):?><article><span class="pill <?= $q['is_active']?'pill-green':'pill-muted'?>"><?= $q['is_active']?'Active':'Inactive'?></span><div><small><?=e($q['category'])?> · <?=e($q['question_type'])?><?= $q['is_required']?' · Required':''?></small><p><?=e($q['prompt'])?></p></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="question_id" value="<?= (int)$q['id']?>"><button class="button button-small"><?= $q['is_active']?'Disable':'Enable'?></button></form></article><?php endforeach;?><?php if(!$questions):?><p class="muted">No questions configured.</p><?php endif;?></div></section></div>
<?php require __DIR__.'/../includes/footer.php';?>